select *
from (
    select plan, avg(monthly_fee) avg_monthly_fee
    from subscriptions
    where plan != 'standard'
    group by plan
) s
where avg_monthly_fee >= 180
order by avg_monthly_fee;

select id, is_flagged, substring(merchant, 1, 2) as merchant_prefix
from transactions
where not is_flagged and account_id in (23, 25, 28);

select customer_id, add_months(end_date, 1) as end_date_plus_months, datediff(current_date(), start_date) as days_since_start_date
from subscriptions
where end_date between '2023-07-18' and '2024-07-01' or monthly_fee is not null;

SELECT id, cost
FROM products
WHERE cost BETWEEN 260 AND 380;

SELECT name
FROM customers
WHERE UPPER(TRIM(name)) = 'CAROL DIAZ' AND name IS NOT NULL;

select credit_limit_bucket, avg_age
from (
    select case when credit_limit >= 14700 then 'high' when credit_limit >= 5100 then 'mid' else 'low' end as credit_limit_bucket, round(avg(age), 2) as avg_age
    from customers
    group by case when credit_limit >= 14700 then 'high' when credit_limit >= 5100 then 'mid' else 'low' end
) as agg
where avg_age >= 69;

select *
from (
    select case when year(last_restock) < 2024 then 'before_2024' when year(last_restock) = 2024 then '2024' else 'after_2024' end last_restock_cohort, count(*) total_count
    from inventory
    group by case when year(last_restock) < 2024 then 'before_2024' when year(last_restock) = 2024 then '2024' else 'after_2024' end
) sub
where total_count >= 5;

select id, account_id
from transactions
where not (amount < 3500 and account_id in (1, 3, 7, 21) and hour(txn_time) between 6 and 14);

SELECT account_type
FROM accounts
WHERE opened_date >= '2025-06-27';

select id, status, shipped_date
from shipments
where shipped_date > '2025-01-01';

SELECT id, opened_date, store_name
FROM stores
WHERE opened_date <= '2025-07-01';

SELECT a.id, a.customer_id
FROM accounts a
WHERE a.opened_date > '2025-03-08' AND NOT EXISTS (SELECT 1 FROM transactions t WHERE t.account_id = a.id AND t.merchant != 'Shell');

SELECT s.start_date, s.monthly_fee, c.city
FROM subscriptions s
LEFT JOIN customers c ON s.customer_id = c.id;

select p.price, p.product_name, i.last_restock
from products p
left join inventory i on p.id = i.product_id;

SELECT o.customer_id, o.store_id, p.method
FROM orders o
LEFT JOIN payments p ON o.id = p.order_id;

SELECT o.shipping_fee, s.delivered_date, s.shipped_date
FROM orders o
LEFT OUTER JOIN shipments s ON o.id = s.order_id;

SELECT sessions.country, customers.city, customers.is_active
FROM sessions
LEFT OUTER JOIN customers ON sessions.customer_id = customers.id;

select store_id, max(units) as max_units, count(*) as row_count
from store_sales
group by store_id;

select country, min(rating) as min_rating
from suppliers
group by country;

SELECT merchant, MAX(amount) - MIN(amount) AS amount_range
FROM transactions
GROUP BY merchant;

select order_id, round(stddev(quantity), 2) as stddev_quantity, count(*) as row_count
from order_items
group by order_id;

SELECT city, SORT_ARRAY(COLLECT_SET(city)) AS city_list
FROM stores
GROUP BY city;

SELECT is_remote, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(job_title))) AS job_title_values, MAX(salary) - MIN(salary) AS salary_range
FROM employees
GROUP BY 1;

SELECT order_id, product_id, MAX(quantity) - MIN(quantity) AS quantity_range
FROM order_items
GROUP BY order_id, product_id;

select is_flagged, count(distinct amount) unique_accounts
from transactions
group by is_flagged;

SELECT is_flagged, SUM(amount) AS total_amount
FROM transactions
GROUP BY is_flagged;

select method, status, count(amount) as amount_count
from payments
group by method, status;

SELECT account_id, COUNT(*) AS total_count, MIN(txn_time) AS min_txn_time
FROM transactions
GROUP BY account_id;

SELECT status, MAX(paid_at) AS latest_paid_at, MAX(amount) AS max_amount
FROM payments
GROUP BY status;

SELECT txn_type, MIN(amount) AS min_amount
FROM transactions
GROUP BY txn_type;

SELECT units, product_id, store_id
FROM store_sales
WHERE NOT (MONTH(sale_date) IN (1, 8, 12) AND (revenue BETWEEN 1200 AND 2600 OR revenue <= 1200));

SELECT id, account_id, IF(is_flagged, 'Yes', 'No') AS is_flagged_label
FROM transactions
WHERE txn_type = 'FEE' AND is_flagged = TRUE;

SELECT *
FROM subscriptions
WHERE monthly_fee <= 120 AND plan IN ('premium', 'enterprise');

SELECT *
FROM customers
WHERE age > 58 AND segment IN ('Corporate', 'SMB', 'Consumer');

select date_format(last_restock, 'yyyy-MM') as last_restock_month, min(last_restock) as first_last_restock
from inventory
group by last_restock_month;

SELECT account_type, MONTH(opened_date) AS opened_month, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values
FROM accounts
GROUP BY account_type, MONTH(opened_date);

SELECT * FROM (SELECT txn_type, merchant, amount FROM transactions WHERE TO_DATE(txn_time) >= '2025-02-16')
PIVOT (AVG(amount) FOR merchant IN ('Grab', '7-Eleven', 'Starbucks', 'Amazon'))
ORDER BY txn_type;

SELECT * FROM (SELECT city, region, sqft FROM stores WHERE UPPER(TRIM(store_name)) = 'OLD TOWN')
PIVOT (MAX(sqft) FOR region IN ('South', 'East'))
ORDER BY city;

select i.store_id, p.price, p.stock_qty
from inventory i
inner join products p on i.product_id = p.id;

SELECT a.opened_date, t.merchant, t.amount
FROM accounts a
INNER JOIN transactions t ON a.id = t.account_id;

SELECT s.id, s.store_name
FROM stores s
WHERE s.store_name LIKE '%Old%' AND s.id IN (SELECT store_id FROM store_sales);
